test("singleDistinct はすべての要素が等しい並びからその値を返す", () => {
  expect(ArrayEx.singleDistinct(["a", "a", "a"])).toEqual(Option.some("a"));
});

test("singleDistinct は異なる値が混ざる並びでは none を返す", () => {
  expect(ArrayEx.singleDistinct(["a", "b", "a"])).toEqual(Option.none);
});

test("singleDistinct は空の並びでは none を返す", () => {
  expect(ArrayEx.singleDistinct([])).toEqual(Option.none);
});

test("singleDistinct は値が null だけの並びでは none を返す", () => {
  expect(ArrayEx.singleDistinct([null, null])).toEqual(Option.none);
});

test("同じ親の兄弟を前面にいるものから選んでも、親と、背面から順の位置が返る", () => {
  expect(Option.unwrap(siblingsOf(["group", "a"]))).toEqual({
    parentName: "home",
    indices: [0, 2],
  });
});

test("親が違うノードを選んでいると、兄弟の位置は無い", () => {
  expect(Option.isSome(siblingsOf(["a", "inner-1"]))).toBe(false);
});

test("artboard とその子を選んでいると、兄弟の位置は無い", () => {
  expect(Option.isSome(siblingsOf(["home", "a"]))).toBe(false);
});

test("何も選んでいなければ、兄弟の位置は無い", () => {
  expect(Option.isSome(siblingsOf([]))).toBe(false);
});

test("兄弟をまとめて前面へ動かすときは、前面にいるものから順に 1 つ後ろへ動かす", () => {
  expect(
    ReorderStep.toChildReorders(ReorderSteps.TowardFront, {
      parentName: "Card",
      indices: [0, 2],
    }),
  ).toEqual([
    { from: { parentName: "Card", index: 2 }, toIndex: 3 },
    { from: { parentName: "Card", index: 0 }, toIndex: 1 },
  ]);
});

test("兄弟をまとめて背面へ動かすときは、背面にいるものから順に 1 つ前へ動かす", () => {
  expect(
    ReorderStep.toChildReorders(ReorderSteps.TowardBack, {
      parentName: "Card",
      indices: [1, 3],
    }),
  ).toEqual([
    { from: { parentName: "Card", index: 1 }, toIndex: 0 },
    { from: { parentName: "Card", index: 3 }, toIndex: 2 },
  ]);
});

test("離れた兄弟をまとめて前面へ動かすと、それぞれ 1 つずつ前面へずれる", () => {
  const reordered = Option.unwrap(
    reorderSelected(["a", "b"], ReorderSteps.TowardFront),
  );

  expect(childNames(reordered, "home")).toEqual(["x", "a", "y", "b", "group"]);
});

test("隣り合う兄弟をまとめて前面へ動かすと、並び順を保ったまま 1 つ前面へずれる", () => {
  const reordered = Option.unwrap(
    reorderSelected(["a", "x"], ReorderSteps.TowardFront),
  );

  expect(childNames(reordered, "home")).toEqual(["b", "a", "x", "y", "group"]);
});

test("離れた兄弟をまとめて背面へ動かすと、それぞれ 1 つずつ背面へずれる", () => {
  const reordered = Option.unwrap(
    reorderSelected(["x", "y"], ReorderSteps.TowardBack),
  );

  expect(childNames(reordered, "home")).toEqual(["x", "a", "y", "b", "group"]);
});

test("隣り合う兄弟をまとめて背面へ動かすと、並び順を保ったまま 1 つ背面へずれる", () => {
  const reordered = Option.unwrap(
    reorderSelected(["b", "y"], ReorderSteps.TowardBack),
  );

  expect(childNames(reordered, "home")).toEqual(["a", "b", "y", "x", "group"]);
});

test("1 つでも最前面にいるものを選んでいると、前面へは動かせない", () => {
  expect(Option.isSome(reorderSelected(["a"], ReorderSteps.TowardFront))).toBe(
    true,
  );
  expect(
    Option.isSome(reorderSelected(["a", "group"], ReorderSteps.TowardFront)),
  ).toBe(false);
});

test("1 つでも最背面にいるものを選んでいると、背面へは動かせない", () => {
  expect(Option.isSome(reorderSelected(["b"], ReorderSteps.TowardBack))).toBe(
    true,
  );
  expect(
    Option.isSome(reorderSelected(["a", "b"], ReorderSteps.TowardBack)),
  ).toBe(false);
});

test("親が違うノードを選んでいると、まとめては動かせない", () => {
  expect([
    Option.isSome(reorderSelected(["a"], ReorderSteps.TowardFront)),
    Option.isSome(reorderSelected(["inner-1"], ReorderSteps.TowardFront)),
  ]).toEqual([true, true]);
  expect(
    Option.isSome(reorderSelected(["a", "inner-1"], ReorderSteps.TowardFront)),
  ).toBe(false);
});

test("まとめて動かしたあと、1 回の取り消しで元の並びに戻る", () => {
  const reordered = Option.unwrap(
    reorderSelected(["a", "b"], ReorderSteps.TowardFront),
  );

  const undone = Option.unwrap(EditorState.undo(reordered));

  expect(childNames(undone, "home")).toEqual(["a", "x", "b", "y", "group"]);
});

test("まとめて動かしても、選んでいたノードは選ばれたままになる", () => {
  const reordered = Option.unwrap(
    reorderSelected(["a", "b"], ReorderSteps.TowardFront),
  );

  expect(
    DocumentSelection.names(EditorState.documentSelection(reordered)),
  ).toEqual(["a", "b"]);
});

test("まとめて前面へ動かしてから背面へ動かすと、元の並びに戻る", () => {
  const forward = Option.unwrap(
    reorderSelected(["a", "b"], ReorderSteps.TowardFront),
  );

  const backward = Option.unwrap(
    EditorState.reorderSelectedNodes(forward, ReorderSteps.TowardBack),
  );

  expect(childNames(backward, "home")).toEqual(["a", "x", "b", "y", "group"]);
});

test("同じ親の兄弟を複数選んでいるときは、動かせる向きの並べ替えと削除が押せる", () => {
  const menu = EditMenu.create(
    EditorState.selectNodes(setupState(), ["title", "panel"]),
    EditMenuTargets.Node,
  );

  expect(enabledOperations(menu)).toEqual([
    EditOperations.BringForward,
    EditOperations.Delete,
  ]);
});

test("最前面にいるものを含む兄弟を複数選んでいるときは、前面へが押せない", () => {
  const menu = EditMenu.create(
    EditorState.selectNodes(setupState(), ["panel", "login"]),
    EditMenuTargets.Node,
  );

  expect([
    isRowEnabled(menu, EditOperations.BringForward),
    isRowEnabled(menu, EditOperations.SendBackward),
  ]).toEqual([false, true]);
});

test("親が違うノードを複数選んでいるときは、削除だけが押せる", () => {
  const menu = EditMenu.create(
    EditorState.selectNodes(stateWithNestedPanel(), ["title", "inner-a"]),
    EditMenuTargets.Node,
  );

  expect(enabledOperations(menu)).toEqual([EditOperations.Delete]);
});

test("同じ親の兄弟をまとめて選んでいるときは ⌘[ でまとめて背面へ動く", async () => {
  await renderOpenedDocument(SampleDocumentWithSameComponentInstances);
  await userEvent.click(within(canvasPane()).getByText("ログイン"));
  await userEvent.click(
    within(propertyPane()).getByRole("button", {
      name: "Select all 2 instances",
    }),
  );

  await userEvent.keyboard("{Meta>}[[{/Meta}");

  expect(rowNames(tree())).toEqual(["home-login", "home-signup", "home-title"]);
});

test("複数選択の一員の行のメニューの Send backward を押すと、選んだものがまとめて背面へ動く", async () => {
  await renderOpenedDocument(SampleDocumentWithSameComponentInstances);
  await userEvent.click(within(canvasPane()).getByText("ログイン"));
  await userEvent.click(
    within(propertyPane()).getByRole("button", {
      name: "Select all 2 instances",
    }),
  );

  rightClickInTree("home-signup");
  await userEvent.click(menuRow("Send backward"));

  expect(rowNames(tree())).toEqual(["home-login", "home-signup", "home-title"]);
});

test("選んでいるノードは ⌘] で兄弟の並びの中を前面へ動く", async () => {
  await renderOpenedDocument();
  await userEvent.click(screen.getByRole("button", { name: "home-title" }));

  await userEvent.keyboard("{Meta>}]{/Meta}");

  expect(rowNames(tree())).toEqual(["home-login", "home-title"]);
});

export type SiblingPositions = Readonly<{
  /** 選んだノードすべての親の名前。 */
  parentName: string;
  /** 選んだノードそれぞれの、親の子の並びの中での位置。小さい順。 */
  indices: readonly [number, ...number[]];
}>;

function offsetOf(step: ReorderStep): number {
  switch (step) {
    case "toward-front":
      return 1;
    case "toward-back":
      return -1;
  }
}

reorderSelectedNodes(
  state: EditorState,
  step: ReorderStep,
): Option<EditorState> {
  const siblings = SiblingPositions.fromSelection(
    EditorState.documentSelection(state),
  );
  if (!Option.isSome(siblings)) {
    return Option.none;
  }
  const reordered = ArrayEx.reduceUntilErr(
    ReorderStep.toChildReorders(step, siblings.value),
    EditorState.document(state),
    (document, reorder) =>
      DesignDocument.reorderNode(document, reorder.from, reorder.toIndex),
  );
  return withEditResult(state, reordered);
},

fromSelection(selection: DocumentSelection): Option<SiblingPositions> {
  const names = DocumentSelection.names(selection);
  const positions = names.flatMap((name): readonly ChildPosition[] => {
    const found = DesignDocument.findChildPosition(selection.document, name);
    return Option.isSome(found) ? [found.value] : [];
  });
  if (positions.length !== names.length) {
    return Option.none;
  }
  const indices = ArrayEx.sortBy(
    positions.map((position) => position.index),
    (index) => index,
  );
  return Option.flatMap(
    ArrayEx.singleDistinct(positions.map((position) => position.parentName)),
    (parentName) =>
      Option.map(
        ArrayEx.first(indices),
        (first): SiblingPositions => ({
          parentName,
          indices: [first, ...ArrayEx.dropFirst(indices)],
        }),
      ),
  );
},

toChildReorders(
  step: ReorderStep,
  from: SiblingPositions,
): readonly ChildReorder[] {
  const ascending: readonly number[] = from.indices;
  // 動く向きの先にいるものから当てる。位置は小さい順なので、前面へなら逆から読む
  const ordered = offsetOf(step) > 0 ? [...ascending].reverse() : ascending;
  return ordered.map((index) => {
    const position: ChildPosition = { parentName: from.parentName, index };
    return { from: position, toIndex: ReorderStep.toIndex(step, position) };
  });
},

function withEditResult(
  state: EditorState,
  edited: Result<DesignDocument, DesignDocumentEditError>,
  continuity: EditContinuity = EditContinuities.Separate,
): Option<EditorState> {
  return Result.isOk(edited)
    ? withEdit(state, edited.value, continuity)
    : Option.none;
}
